<?php
require __DIR__.'/includes/module.php';$u=require_auth();require_permission('invoices.view');$bid=(int)$u['business_id'];$pdo=db();$status=trim((string)($_GET['status']??''));$q=trim((string)($_GET['q']??''));$sql='SELECT i.*,c.name customer FROM invoices i JOIN customers c ON c.id=i.customer_id WHERE i.business_id=?';$args=[$bid];if($status==='Outstanding')$sql.=" AND i.status IN ('Issued','Overdue','Partially Paid') AND i.total>i.amount_paid";if($q!==''){$sql.=' AND (i.invoice_number LIKE ? OR c.name LIKE ?)';array_push($args,'%'.$q.'%','%'.$q.'%');}$sql.=' ORDER BY i.invoice_date DESC,i.id DESC';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$sum=$pdo->prepare("SELECT COUNT(*) invoices,COALESCE(SUM(CASE WHEN status<>'Void' THEN total ELSE 0 END),0) total,COALESCE(SUM(CASE WHEN status<>'Void' THEN total-amount_paid ELSE 0 END),0) outstanding FROM invoices WHERE business_id=?");$sum->execute([$bid]);$stats=$sum->fetch();page_start('Invoices','invoices');module_css('invoices');?><div class="section-head"><div><span class="eyebrow">BILLING</span><h1>Invoices</h1><p>Professional billing with a clear view of every balance.</p></div><a class="button primary" href="invoice-create.php"><i class="ti ti-plus"></i> Create invoice</a></div><div class="summary-grid"><div class="summary-tile"><small>Invoices</small><strong><?=$stats['invoices']?></strong></div><div class="summary-tile"><small>Total billed</small><strong><?=money($stats['total'])?></strong></div><div class="summary-tile"><small>Outstanding</small><strong><?=money($stats['outstanding'])?></strong></div></div><div class="content-card"><form class="toolbar"><input class="search" name="q" value="<?=e($q)?>" placeholder="Search invoice or customer"><button class="button secondary">Search</button><select name="status" class="search" style="min-width:130px"><option value="">All statuses</option><option value="Outstanding" <?=$status==='Outstanding'?'selected':''?>>Outstanding</option></select></form><div class="table-scroll"><table class="data-table"><thead><tr><th>INVOICE</th><th>CUSTOMER</th><th>ISSUED</th><th>DUE</th><th>TOTAL</th><th>PAID</th><th>STATUS</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a class="table-strong" href="invoice-view.php?id=<?=(int)$r['id']?>"><?=e($r['invoice_number'])?></a></td><td><?=e($r['customer'])?></td><td><?=fmt_date($r['invoice_date'])?></td><td><?=fmt_date($r['due_date'])?></td><td class="table-strong"><?=money($r['total'])?></td><td><?=money($r['amount_paid'])?></td><td><span class="status <?=strtolower(str_replace(' ','-',e($r['status'])))?>"><?=e($r['status'])?></span></td><td><a class="link-button" href="invoice-view.php?id=<?=(int)$r['id']?>">Open</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="8" class="empty-row">No invoices match this view.</td></tr><?php endif?></tbody></table></div></div><?php page_end();
